* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  color: #111827;
  background: #f9fafb;
}

.events-screen {
  display: grid;
  gap: 16px;
  max-width: 1040px;
  margin: 0 auto;
  padding: 16px;
}

@media (min-width: 900px) {
  .events-screen {
    grid-template-columns: minmax(0, 3fr) minmax(0, 2fr);
    gap: 24px;
    align-items: start;
  }
}

.preview {
  display: grid;
  gap: 12px;
  min-width: 0;
}

.preview-image {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 12px;
}

.preview-title {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  line-height: 1.3;
}

.event-panel {
  display: grid;
  gap: 12px;
  min-width: 0;
}

.filter-field {
  display: grid;
  gap: 6px;
  font-size: 14px;
  font-weight: 600;
}

.filter {
  min-height: 40px;
  padding: 8px 12px;
  border: 1px solid #d1d5db;
  border-radius: 8px;
  font: inherit;
  font-weight: 400;
}

.event-list {
  display: grid;
  gap: 8px;
}

.event-row {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  width: 100%;
  padding: 12px 16px;
  border: 1px solid #e5e7eb;
  border-radius: 10px;
  background: #ffffff;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.event-row[aria-pressed='true'] {
  border-color: #2563eb;
  background: #eff6ff;
}

.event-thumb {
  flex: none;
  width: 64px;
  height: 48px;
  border-radius: 6px;
  object-fit: cover;
}

.event-text {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.event-title {
  font-size: 16px;
  font-weight: 600;
  color: #111827;
}

.event-subtitle {
  font-size: 14px;
  color: #4b5563;
}

.event-meta {
  font-size: 13px;
  color: #6b7280;
}

.event-time {
  font-size: 13px;
  font-weight: 600;
  color: #2563eb;
}

.no-events {
  margin: 0;
  padding: 12px 16px;
  border: 1px dashed #d1d5db;
  border-radius: 10px;
  color: #4b5563;
}
